CREATE TABLE `inventories_operation_types` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort` int(11) DEFAULT NULL,
  `sequence_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reservation_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'at_confirm',
  `reservation_days_before` int(11) DEFAULT '0',
  `reservation_days_before_priority` int(11) DEFAULT '0',
  `product_label_format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lot_label_format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `package_label_to_print` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barcode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_backorder` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ask',
  `move_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'direct',
  `show_entire_packs` tinyint(1) DEFAULT '0',
  `use_create_lots` tinyint(1) DEFAULT '0',
