CREATE TABLE `pos_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `floating_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tracking_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receipt_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `access_token` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origin` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `sequence_number` int(10) unsigned NOT NULL DEFAULT '0',
  `ordered_at` timestamp NULL DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `shipped_at` date DEFAULT NULL,
  `currency_rate` decimal(15,4) NOT NULL DEFAULT '1.0000',
  `amount_untaxed` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_tax` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_total` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_paid` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_return` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_difference` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `total_cost` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `margin` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `margin_percent` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `tip_amount` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `amount_rounding` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `print_count` int(10) unsigned NOT NULL DEFAULT '0',
  `customer_count` int(10) unsigned NOT NULL DEFAULT '0',
  `note` text COLLATE utf8mb4_unicode_ci,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_to_invoice` tinyint(1) NOT NULL DEFAULT '0',
  `is_invoiced` tinyint(1) NOT NULL DEFAULT '0',
  `is_tipped` tinyint(1) NOT NULL DEFAULT '0',
  `is_takeaway` tinyint(1) NOT NULL DEFAULT '0',
  `is_booked` tinyint(1) NOT NULL DEFAULT '0',
  `preparation_state` json DEFAULT NULL,
  `is_cost_computed` tinyint(1) NOT NULL DEFAULT '0',
  `is_edited` tinyint(1) NOT NULL DEFAULT '0',
  `has_failed_operation` tinyint(1) NOT NULL DEFAULT '0',
  `session_id` bigint(20) unsigned NOT NULL,
  `config_id` bigint(20) unsigned NOT NULL,
  `partner_id` bigint(20) unsigned DEFAULT NULL,
  `price_list_id` bigint(20) unsigned DEFAULT NULL,
  `fiscal_position_id` bigint(20) unsigned DEFAULT NULL,
  `currency_id` bigint(20) unsigned DEFAULT NULL,
  `operation_id` bigint(20) unsigned DEFAULT NULL,
  `procurement_group_id` bigint(20) unsigned DEFAULT NULL,
  `refunded_order_id` bigint(20) unsigned DEFAULT NULL,
  `account_move_id` bigint(20) unsigned DEFAULT NULL,
  `table_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `company_id` bigint(20) unsigned NOT NULL,
  `creator_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pos_orders_uuid_unique` (`uuid`),
  KEY `pos_orders_partner_id_foreign` (`partner_id`),
  KEY `pos_orders_price_list_id_foreign` (`price_list_id`),
  KEY `pos_orders_fiscal_position_id_foreign` (`fiscal_position_id`),
  KEY `pos_orders_currency_id_foreign` (`currency_id`),
  KEY `pos_orders_operation_id_foreign` (`operation_id`),
  KEY `pos_orders_procurement_group_id_foreign` (`procurement_group_id`),
  KEY `pos_orders_refunded_order_id_foreign` (`refunded_order_id`),
  KEY `pos_orders_account_move_id_foreign` (`account_move_id`),
  KEY `pos_orders_user_id_foreign` (`user_id`),
  KEY `pos_orders_company_id_foreign` (`company_id`),
  KEY `pos_orders_creator_id_foreign` (`creator_id`),
  KEY `pos_orders_session_id_state_index` (`session_id`,`state`),
  KEY `pos_orders_config_id_ordered_at_index` (`config_id`,`ordered_at`),
  KEY `pos_orders_name_index` (`name`),
  KEY `pos_orders_reference_index` (`reference`),
  KEY `pos_orders_state_index` (`state`),
  KEY `pos_orders_ordered_at_index` (`ordered_at`),
  KEY `pos_orders_table_id_foreign` (`table_id`),
  CONSTRAINT `pos_orders_account_move_id_foreign` FOREIGN KEY (`account_move_id`) REFERENCES `accounts_account_moves` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `pos_orders_config_id_foreign` FOREIGN KEY (`config_id`) REFERENCES `pos_configs` (`id`),
  CONSTRAINT `pos_orders_creator_id_foreign` FOREIGN KEY (`creator_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_fiscal_position_id_foreign` FOREIGN KEY (`fiscal_position_id`) REFERENCES `accounts_fiscal_positions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_operation_id_foreign` FOREIGN KEY (`operation_id`) REFERENCES `inventories_operations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_partner_id_foreign` FOREIGN KEY (`partner_id`) REFERENCES `partners_partners` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_price_list_id_foreign` FOREIGN KEY (`price_list_id`) REFERENCES `products_product_price_lists` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_procurement_group_id_foreign` FOREIGN KEY (`procurement_group_id`) REFERENCES `inventories_procurement_groups` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_refunded_order_id_foreign` FOREIGN KEY (`refunded_order_id`) REFERENCES `pos_orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `pos_sessions` (`id`),
  CONSTRAINT `pos_orders_table_id_foreign` FOREIGN KEY (`table_id`) REFERENCES `pos_tables` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pos_orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
