  `outstanding_account_id` bigint(20) unsigned DEFAULT NULL,
  `company_id` bigint(20) unsigned NOT NULL,
  `creator_id` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pos_payment_methods_journal_id_foreign` (`journal_id`),
  KEY `pos_payment_methods_receivable_account_id_foreign` (`receivable_account_id`),
  KEY `pos_payment_methods_outstanding_account_id_foreign` (`outstanding_account_id`),
  KEY `pos_payment_methods_company_id_foreign` (`company_id`),
  KEY `pos_payment_methods_creator_id_foreign` (`creator_id`),
  KEY `pos_payment_methods_type_index` (`type`),
